async function get(url){const r=await fetch(url,{cache:"no-store"});const j=await r.json().catch(()=>null);if(!r.ok)throw new Error(j&&j.detail||j&&j.error||"Market request failed");return j;}
function marketCacheKey(){return "eti-market-cache:"+S.venue+":"+S.market+":"+S.category+":"+S.symbol+":"+S.interval;}
