function drawFallbackChart(){const canvas=S.fallbackCanvas;if(!canvas||!S.candles.length)return;const rect=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2),w=Math.max(320,Math.floor(rect.width)),h=Math.max(220,Math.floor(rect.height));canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);const ctx=canvas.getContext("2d");if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const rows=S.candles.slice(-120),lo=Math.min(...rows.map(x=>x.low)),hi=Math.max(...rows.map(x=>x.high)),pad={l:12,r:76,t:16,b:28},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b,range=Math.max(hi-lo,Math.abs(hi)*.0001,1e-9),y=v=>pad.t+(hi-v)/range*ch;ctx.font="10px system-ui";ctx.strokeStyle="#19324d";ctx.fillStyle="#8ea6c2";ctx.lineWidth=1;for(let k=0;k<=4;k++){const yy=pad.t+ch*k/4;ctx.beginPath();ctx.moveTo(pad.l,yy);ctx.lineTo(w-pad.r,yy);ctx.stroke();ctx.fillText(px(hi-range*k/4),w-pad.r+7,yy+3);}const step=cw/rows.length,body=Math.max(2,Math.min(9,step*.62));rows.forEach((c,i)=>{const x=pad.l+i*step+step/2,up=c.close>=c.open;ctx.strokeStyle=up?"#25d5a0":"#f36a80";ctx.fillStyle=ctx.strokeStyle;ctx.beginPath();ctx.moveTo(x,y(c.high));ctx.lineTo(x,y(c.low));ctx.stroke();const top=y(Math.max(c.open,c.close)),bottom=y(Math.min(c.open,c.close));ctx.fillRect(x-body/2,top,body,Math.max(1,bottom-top));});if(S.liquidityFvg){const z=S.liquidityFvg.precision&&S.liquidityFvg.precision.best;if(z){const a=y(z.zone.upper),b=y(z.zone.lower),col=z.highlight==="green"?"#25d5a0":z.highlight==="red"?"#f36a80":"#e6c36a";ctx.fillStyle=z.highlight==="green"?"rgba(37,213,160,.16)":"rgba(230,195,106,.1)";ctx.fillRect(pad.l,Math.min(a,b),cw,Math.max(1,Math.abs(b-a)));ctx.strokeStyle=col;ctx.setLineDash([4,4]);[a,b].forEach(v=>{ctx.beginPath();ctx.moveTo(pad.l,v);ctx.lineTo(w-pad.r,v);ctx.stroke();});ctx.setLineDash([]);ctx.fillStyle=col;ctx.fillText(z.direction+" FVG · CE "+px(z.entry.price),pad.l+6,Math.max(13,Math.min(a,b)-4));}const band=S.liquidityFvg.manipulation&&S.liquidityFvg.manipulation.estimatedReach;if(band){const a=y(band.high),b=y(band.low);ctx.fillStyle="rgba(181,140,255,.08)";ctx.fillRect(pad.l,Math.min(a,b),cw,Math.max(1,Math.abs(b-a)));ctx.strokeStyle="#b58cff";ctx.setLineDash([3,5]);[a,b].forEach(v=>{ctx.beginPath();ctx.moveTo(pad.l,v);ctx.lineTo(w-pad.r,v);ctx.stroke();});ctx.setLineDash([]);}}ctx.fillStyle="#8ea6c2";ctx.fillText(S.symbol+" · "+S.interval+" · "+rows.length+" bars",pad.l,h-8);const last=rows[rows.length-1];ctx.fillStyle="#e8f0fc";ctx.fillText("Last "+px(last.close),pad.l+8,pad.t+12);}
function init(){const n=$("tt-chart");try{if(!window.LightweightCharts)throw new Error("External chart library unavailable");S.chart=LightweightCharts.createChart(n,{width:n.clientWidth,height:n.clientHeight,layout:{background:{color:"#000000"},textColor:"#8ea6c2"},grid:{vertLines:{color:"#141a22"},horzLines:{color:"#141a22"}},rightPriceScale:{borderColor:"#2a3342"},timeScale:{borderColor:"#2a3342",timeVisible:true},crosshair:{mode:LightweightCharts.CrosshairMode.Normal}});S.overlayCanvas=document.createElement("canvas");S.overlayCanvas.className="tt-liq-overlay";S.overlayCanvas.setAttribute("aria-hidden","true");n.appendChild(S.overlayCanvas);S.candle=S.chart.addCandlestickSeries({upColor:"#25d5a0",downColor:"#f36a80",borderUpColor:"#25d5a0",borderDownColor:"#f36a80",wickUpColor:"#25d5a0",wickDownColor:"#f36a80",priceFormat:{type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)}});window.ETIProTerminalChart={priceToCoordinate:price=>{const p=Number(price);return Number.isFinite(p)&&S.candle?S.candle.priceToCoordinate(p):null;},timeToCoordinate:time=>{const t=Math.floor(Number(time)/1000);return Number.isFinite(t)&&S.chart?S.chart.timeScale().timeToCoordinate(t):null;}};S.volume=S.chart.addHistogramSeries({priceFormat:{type:"volume"},priceScaleId:"volume",scaleMargins:{top:.83,bottom:0},lastValueVisible:false,priceLineVisible:false});S.ema20=S.chart.addLineSeries({color:"#f2c14e",lineWidth:1,priceLineVisible:false,lastValueVisible:false,priceFormat:{type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)}});S.ema50=S.chart.addLineSeries({color:"#56adff",lineWidth:1,priceLineVisible:false,lastValueVisible:false,priceFormat:{type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)}});S.chart.subscribeCrosshairMove(p=>{const d=p&&p.seriesData&&p.seriesData.get(S.candle);$("tt-ohlc").textContent=d?"O "+px(d.open)+" H "+px(d.high)+" L "+px(d.low)+" C "+px(d.close):"Crosshair: inspect candle OHLC";});S.chart.subscribeClick(p=>{if(!p||!p.point)return;const v=S.candle.coordinateToPrice(p.point.y);if(!Number.isFinite(v))return;if(S.drawMode){if(S.candle)S.drawnLevels.push(S.candle.createPriceLine({price:v,color:"#d5a8ff",lineWidth:1,lineStyle:2,axisLabelVisible:true,title:"ETI level"}));else S.drawnLevels.push({fallbackPrice:v});saveChartPrefs();S.drawMode=false;$("tt-draw-level").classList.remove("on");}else $("tt-entry").value=v.toFixed(S.pricePrecision);});}catch(e){S.chart=null;S.candle=null;S.fallbackCanvas=document.createElement("canvas");S.fallbackCanvas.className="tt-chart-canvas-fallback";S.fallbackCanvas.setAttribute("role","img");S.fallbackCanvas.setAttribute("aria-label","Fallback candlestick chart");n.replaceChildren(S.fallbackCanvas);status("Chart library unavailable · native chart fallback active",true);}new ResizeObserver(()=>{if(S.chart){S.chart.applyOptions({width:n.clientWidth,height:n.clientHeight});drawLiquidityOverlay();}else drawFallbackChart();}).observe(n);}
function initMultiCharts(){if(!window.LightweightCharts)return;["5m","15m","1h","4h"].forEach(tf=>{const host=$("tt-multi-"+tf);if(!host)return;const chart=LightweightCharts.createChart(host,{width:host.clientWidth,height:host.clientHeight,layout:{background:{color:"#000000"},textColor:"#8ea6c2",fontSize:10},grid:{vertLines:{color:"#141a22"},horzLines:{color:"#141a22"}},rightPriceScale:{borderColor:"#2a3342"},timeScale:{borderColor:"#2a3342",timeVisible:true,secondsVisible:false},crosshair:{mode:LightweightCharts.CrosshairMode.Normal},handleScroll:true,handleScale:true});const series=chart.addCandlestickSeries({upColor:"#25d5a0",downColor:"#f36a80",borderUpColor:"#25d5a0",borderDownColor:"#f36a80",wickUpColor:"#25d5a0",wickDownColor:"#f36a80",priceFormat:{type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)}});S.multiCharts[tf]={chart,series,host};chart.timeScale().subscribeVisibleTimeRangeChange(range=>{if(!range||S.syncLock)return;S.syncLock=true;Object.keys(S.multiCharts).forEach(key=>{const other=S.multiCharts[key];if(other&&other.chart!==chart){try{other.chart.timeScale().setVisibleRange(range)}catch(e){}}});if(S.chart&&S.chart!==chart){try{S.chart.timeScale().setVisibleRange(range)}catch(e){}}S.syncLock=false;});});if(S.chart)S.chart.timeScale().subscribeVisibleTimeRangeChange(range=>{if(!range||S.syncLock)return;S.syncLock=true;Object.values(S.multiCharts).forEach(other=>{try{other.chart.timeScale().setVisibleRange(range)}catch(e){}});S.syncLock=false;});}
async function loadMultiCharts(){ const frames=["5m","15m","1h","4h"]; if(!Object.keys(S.multiCharts).length){$("tt-multi-status").textContent="Chart library unavailable";return;} $("tt-multi-status").textContent="Synchronizing "+S.venue+" timeframes…"; const results=await Promise.allSettled(frames.map(async tf=>{const p=new URLSearchParams({venue:S.venue,market:S.market,category:S.category,symbol:S.symbol,interval:tf,limit:"180"});return [tf,await get("/api/market/klines?"+p.toString())];})); let good=0;results.forEach(r=>{if(r.status!=="fulfilled")return;const tf=r.value[0],rows=r.value[1]||[],data=rows.map(k=>({time:Math.floor(Number(k[0])/1000),open:Number(k[1]),high:Number(k[2]),low:Number(k[3]),close:Number(k[4])})).filter(k=>Number.isFinite(k.time)&&k.open>0&&k.high>0&&k.low>0&&k.close>0);const pane=S.multiCharts[tf];if(!pane||!data.length)return;pane.series.applyOptions({priceFormat:{type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)}});pane.series.setData(data);S.multiCandles[tf]=data;pane.chart.timeScale().fitContent();good++;}); $("tt-multi-status").textContent=good+"/4 "+S.venue+" timeframes loaded · linked pan/zoom";}
function rowsToCandles(rows){return (rows||[]).map(r=>Array.isArray(r)?{time:Math.floor(Number(r[0])/1000),open:Number(r[1]),high:Number(r[2]),low:Number(r[3]),close:Number(r[4]),volume:Number(r[5])}:r).filter?null:null;}
function ema(p){let prev=null,k=2/(p+1);return S.candles.map(c=>({time:c.time,value:(prev=prev===null?c.close:c.close*k+prev*(1-k))}));}
function emaVals(p){let prev=null,k=2/(p+1);return S.candles.map(c=>(prev=prev===null?c.close:c.close*k+prev*(1-k)));}
function rsi(){const c=S.candles,p=14;if(c.length<=p)return null;let g=0,l=0;for(let i=1;i<=p;i++){let d=c[i].close-c[i-1].close;if(d>0)g+=d;else l-=d;}let ag=g/p,al=l/p;for(let i=p+1;i<c.length;i++){let d=c[i].close-c[i-1].close;ag=(ag*(p-1)+Math.max(d,0))/p;al=(al*(p-1)+Math.max(-d,0))/p;}return al===0?100:100-100/(1+ag/al);}
function macd(){const a=emaVals(12),b=emaVals(26);if(!a.length)return null;const d=a.map((x,i)=>x-b[i]);let s=null,k=2/10;d.forEach(x=>s=s===null?x:x*k+s*(1-k));return {line:d.at(-1),signal:s};}
function fvg(){const out=[];for(let i=2;i<S.candles.length;i++){const c=S.candles[i],p=S.candles[i-2];if(c.low>p.high)out.push({time:c.time,position:"belowBar",color:"#25d5a0",shape:"arrowUp",text:"Bull FVG"});else if(c.high<p.low)out.push({time:c.time,position:"aboveBar",color:"#f36a80",shape:"arrowDown",text:"Bear FVG"});}return out;}
function drawLiquidityOverlay(){const canvas=S.overlayCanvas;if(!canvas||!S.chart||!S.candle)return;const host=$("tt-chart"),rect=host.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2),w=Math.max(1,Math.floor(rect.width)),h=Math.max(1,Math.floor(rect.height));canvas.width=Math.floor(w*dpr);canvas.height=Math.floor(h*dpr);const x=canvas.getContext("2d");if(!x)return;x.setTransform(dpr,0,0,dpr,0,0);x.clearRect(0,0,w,h);const plotW=Math.max(1,w-72),lf=S.liquidityFvg;if(!lf)return;const y=v=>S.candle.priceToCoordinate(Number(v));const zone=lf.precision&&lf.precision.best;if(zone){const a=y(zone.zone.upper),b=y(zone.zone.lower);if(a!==null&&b!==null&&Number.isFinite(a)&&Number.isFinite(b)){const top=Math.max(0,Math.min(a,b)),bottom=Math.min(h,Math.max(a,b)),green=zone.highlight==="green",color=green?"#25d5a0":zone.highlight==="red"?"#f36a80":"#e6c36a";x.fillStyle=green?"rgba(37,213,160,.15)":zone.highlight==="red"?"rgba(243,106,128,.09)":"rgba(230,195,106,.10)";x.fillRect(0,top,plotW,Math.max(1,bottom-top));x.strokeStyle=color;x.lineWidth=1.3;x.setLineDash([5,4]);[a,b].forEach(v=>{x.beginPath();x.moveTo(0,v);x.lineTo(plotW,v);x.stroke();});x.setLineDash([]);x.fillStyle=color;x.font="bold 10px system-ui";x.fillText((green?"QUALIFIED ":"")+zone.direction+" FVG · CE "+px(zone.entry.price),8,Math.max(13,top-5));}}const band=lf.manipulation&&lf.manipulation.estimatedReach;if(band){const a=y(band.high),b=y(band.low);if(a!==null&&b!==null&&Number.isFinite(a)&&Number.isFinite(b)){const top=Math.max(0,Math.min(a,b)),bottom=Math.min(h,Math.max(a,b));x.fillStyle="rgba(181,140,255,.07)";x.fillRect(0,top,plotW,Math.max(1,bottom-top));x.strokeStyle="rgba(181,140,255,.8)";x.setLineDash([3,5]);[a,b].forEach(v=>{x.beginPath();x.moveTo(0,v);x.lineTo(plotW,v);x.stroke();});x.setLineDash([]);x.fillStyle="#c8a9ff";x.font="10px system-ui";x.fillText("ESTIMATED SWEEP REACH",8,Math.max(12,top-4));}}(lf.pools||[]).slice(0,8).forEach(p=>{const yy=y(p.price);if(yy===null||!Number.isFinite(yy))return;x.strokeStyle=p.side==="buy_side"?"rgba(181,140,255,.72)":"rgba(86,173,255,.72)";x.setLineDash([2,5]);x.beginPath();x.moveTo(0,yy);x.lineTo(plotW,yy);x.stroke();x.setLineDash([]);});}
function render(){const c=S.candles;if(!c.length)return;if(S.chart&&S.candle){const priceFormat={type:"price",precision:S.pricePrecision,minMove:Math.pow(10,-S.pricePrecision)};S.candle.applyOptions({priceFormat});S.ema20.applyOptions({priceFormat});S.ema50.applyOptions({priceFormat});if(S.line)S.line.applyOptions({priceFormat});if(S.area)S.area.applyOptions({priceFormat});S.candle.setData(c.map(x=>({time:x.time,open:x.open,high:x.high,low:x.low,close:x.close})));S.volume.setData(c.map(x=>({time:x.time,value:x.volume,color:x.close>=x.open?"rgba(37,213,160,.3)":"rgba(243,106,128,.3)"})));S.ema20.setData(ema(20));S.ema50.setData(ema(50));S.ema20.applyOptions({visible:S.overlays.ema20});S.ema50.applyOptions({visible:S.overlays.ema50});S.volume.applyOptions({visible:S.overlays.volume});const engineMarkers=S.signal&&S.signal.chart?(S.signal.chart.markers||[]).map(m=>({time:Math.floor(m.time/1000),position:m.label==="BUY"?"belowBar":"aboveBar",color:m.label==="BUY"?"#25d5a0":"#f36a80",shape:m.label==="BUY"?"arrowUp":"arrowDown",text:m.label+" "+m.score})):[];const liquidityMarkers=[];if(S.liquidityFvg&&S.liquidityFvg.latestSweep){const sw=S.liquidityFvg.latestSweep,ts=Math.floor(Number(sw.time)/1000);if(S.candles.some(x=>x.time===ts))liquidityMarkers.push({time:ts,position:sw.direction==="BUY"?"belowBar":"aboveBar",color:"#d5a8ff",shape:"circle",text:(sw.side==="buy_side"?"BSL":"SSL")+" SWEEP"});}S.candle.setMarkers(fvg().slice(-50).concat(engineMarkers,liquidityMarkers));S.levelLines.forEach(x=>{try{S.candle.removePriceLine(x)}catch(e){}});S.levelLines=[];if(S.signal){const lev=S.signal.chart&&S.signal.chart.levels;const levels=[["ENTRY",S.signal.entry||lev&&lev.entry,"#56adff"],["STOP",S.signal.stopLoss||lev&&lev.stopLoss,"#f36a80"],["TP1",S.signal.targets&&S.signal.targets[0]&&S.signal.targets[0].price,"#25d5a0"],["TP2",S.signal.targets&&S.signal.targets[1]&&S.signal.targets[1].price,"#25d5a0"],["TP3",S.signal.targets&&S.signal.targets[2]&&S.signal.targets[2].price,"#25d5a0"]];levels.forEach(x=>{if(Number.isFinite(Number(x[1]))&&Number(x[1])>0)S.levelLines.push(S.candle.createPriceLine({price:Number(x[1]),color:x[2],lineWidth:1,lineStyle:2,axisLabelVisible:true,title:x[0]}));});}
if(S.liquidityFvg){const lf=S.liquidityFvg;const add=(title,price,color,style=2)=>{const p=Number(price);if(Number.isFinite(p)&&p>0)S.levelLines.push(S.candle.createPriceLine({price:p,color,lineWidth:1,lineStyle:style,axisLabelVisible:true,title}));};(lf.pools||[]).slice(0,8).forEach(p=>add((p.side==="buy_side"?"BSL":"SSL")+" · "+p.touches+" tests",p.price,p.side==="buy_side"?"#b58cff":"#56adff",2));if(lf.latestSweep)add("SWEPT "+lf.latestSweep.side.toUpperCase(),lf.latestSweep.level,"#d5a8ff",0);if(lf.manipulation&&lf.manipulation.estimatedReach){add("SWEEP REACH LOW",lf.manipulation.estimatedReach.low,"#d5a8ff",3);add("SWEEP REACH HIGH",lf.manipulation.estimatedReach.high,"#d5a8ff",3);}const z=lf.precision&&lf.precision.best;if(z){const col=z.highlight==="green"?"#25d5a0":z.highlight==="red"?"#f36a80":"#e6c36a";add("LIQ-FVG "+z.direction+" LOWER",z.zone.lower,col,2);add("LIQ-FVG "+z.direction+" UPPER",z.zone.upper,col,2);add("CE ENTRY "+px(z.entry.price),z.entry.price,col,0);if(z.stopLoss)add("LIQ-FVG STOP",z.stopLoss,"#f36a80",2);(z.targets||[]).forEach((t,i)=>add("LIQ-FVG TP"+(i+1),t.price,"#25d5a0",2));}}
if(S.line)S.line.setData(c.map(x=>({time:x.time,value:x.close})));if(S.area)S.area.setData(c.map(x=>({time:x.time,value:x.close})));S.chart.timeScale().fitContent();drawLiquidityOverlay();}else drawFallbackChart();renderChartInterpretation();$("tt-count").textContent=c.length+" bars · "+S.interval;$("tt-chart-label").textContent=S.venue.toUpperCase()+" · "+S.market+" · "+S.category+" · "+S.symbol;$("tt-rsi").textContent=rsi()===null?"—":fmt(rsi(),1);$("tt-rsi-note").textContent=rsi()===null?"Insufficient history":rsi()>=70?"Overbought zone":rsi()<=30?"Oversold zone":"Neutral range";const m=macd();$("tt-macd").textContent=m?fmt(m.line,5):"—";$("tt-macd-note").textContent=m?(m.line>=m.signal?"Above signal line":"Below signal line"):"Insufficient history";const a=emaVals(20),b=emaVals(50),last=c.at(-1);$("tt-ema").textContent=last?(a.at(-1)>b.at(-1)?"Bullish alignment":"Bearish alignment"):"—";$("tt-fvg").textContent=String(fvg().length);const hi=Math.max(...c.slice(-20).map(x=>x.high)),lo=Math.min(...c.slice(-20).map(x=>x.low));const pairs=[["Latest close",px(last.close)],["20-bar high",px(hi)],["20-bar low",px(lo)],["FVG observations",String(fvg().length)],["Loaded candles",String(c.length)]];$("tt-structure").replaceChildren(...pairs.map(x=>{const d=document.createElement("div"),a=document.createElement("span"),b=document.createElement("b");a.textContent=x[0];b.textContent=x[1];d.append(a,b);return d;}));}
const CHART_GLOSSARY=[
 {term:"ORDER",meaning:"An order-price annotation or marker. By itself it does not establish that an order was sent, accepted, open or filled.",why:"Chart studies, manual drawings, strategy plans and exchange order overlays can all display prices. Only authenticated venue order records with an order ID and status prove an exchange order.",next:"Check venue, symbol, side, order ID, order type, quantity, reduce-only flag and status (new, partially filled, filled, cancelled or rejected). If those details are unavailable, treat ORDER as an unverified reference and do not assume a position exists."},
 {term:"ENTRY / CE ENTRY",meaning:"The planned or strategy-calculated price at which a position could be opened. CE means consequent encroachment, commonly the 50% midpoint of an FVG.",why:"A level is a location, not a trigger. Price may never revisit it, may pass through it, or the setup may become invalid first.",next:"Wait for the setup's confirmation and retest. Check that the plan is current, correctly sided, affordable and still has positive net reward-to-risk after fees and slippage."},
 {term:"STOP / SL",meaning:"The planned stop-loss or structural invalidation price.",why:"It defines where the trade thesis is considered wrong and limits planned loss, subject to gaps and execution slippage.",next:"Set it before entry, size the position from the stop distance, and never widen it to avoid taking a loss. Confirm futures liquidation is safely beyond the stop."},
 {term:"TP1 / TP2 / TP3",meaning:"Sequential take-profit targets, usually at projected structure or liquidity levels.",why:"They provide staged exit points and help manage reward against risk.",next:"Follow the plan's partial-close percentages. Reassess at each target; trail only when the strategy confirms continuation. Targets are not guaranteed fills."},
 {term:"BSL / SSL",meaning:"Buy-side liquidity (above highs) and sell-side liquidity (below lows): areas where stop orders and breakout orders may cluster.",why:"Price can be attracted to these areas, but a liquidity pool is inferred from price structure; it is not a view of every trader's actual stop order.",next:"Mark them as potential draw-on-liquidity targets. Wait for price reaction, sweep/reclaim or acceptance before choosing a direction. Test counts measure repeated touches, not guaranteed liquidity volume."},
 {term:"SWEEP / SWEPT BUY_SIDE / SWEPT SELL_SIDE",meaning:"Price trades beyond a prior high or low and then closes back through the level; the label identifies the side that was swept.",why:"A failed breakout can trap breakout traders and may precede reversal, while a sustained break can instead be continuation.",next:"Wait for a completed-candle reclaim plus displacement or BOS/CHoCH and then a retest. Do not fade a sweep without confirmation."},
 {term:"SWEEP REACH HIGH / LOW",meaning:"An estimated band for a possible liquidity-sweep reach, generated by the analysis model.",why:"It is a scenario envelope, not a confirmed order-book wall, guaranteed target or precise forecast.",next:"Use it as a watch area only. Require fresh price action and independent structure/liquidity confirmation; invalidate it when the underlying analysis expires."},
 {term:"FVG / BULL FVG / BEAR FVG",meaning:"Fair Value Gap: a three-candle imbalance where the first and third candle ranges do not overlap in the relevant direction.",why:"Price may revisit the imbalance, but gaps can remain unfilled, be partially mitigated or fail.",next:"Prefer fresh, unmitigated zones aligned with trend and structure. Wait for a reaction inside the zone; avoid treating every FVG as an entry."},
 {term:"ORDER BLOCK",meaning:"A candle/price zone identified by the structure model as a potential origin area of an impulsive move.",why:"It may act as a reaction area, but is an analytical approximation, not proof of institutional orders.",next:"Check whether it is mitigated or invalidated, whether displacement and structure support it, and whether a retest gives a defensible stop."},
 {term:"BOS / CHoCH",meaning:"Break of Structure indicates a break in the prevailing swing structure. Change of Character indicates a break against the prior structural direction and a possible transition.",why:"They describe market structure, not certainty of a trend change. A wick-only break may be less reliable than a confirmed close.",next:"Use the timeframe and swing level shown. Prefer a completed-candle close, then look for retest and multi-timeframe alignment. Stand aside when timeframes conflict."},
 {term:"SUPPORT / RESISTANCE",meaning:"Price areas where prior trading or swing reactions suggest demand or supply may respond.",why:"These are zones, not exact barriers; levels can break, flip roles or be swept.",next:"Observe rejection, acceptance and retests. Do not place a stop exactly on an obvious level without considering spread and volatility."},
 {term:"EMA 20 / 50 / 200",meaning:"Exponential moving averages that weight recent closes more heavily; short/long alignment helps describe trend and dynamic areas.",why:"Stacking and slope can show directional regime, but moving averages lag and whipsaw in ranges.",next:"Use alignment as context, not a standalone entry. Avoid chasing after an extended move; wait for pullback and structure confirmation."},
 {term:"VWAP",meaning:"Volume Weighted Average Price for the displayed session/window.",why:"It is a volume-weighted reference for average traded price; holding above/below can describe intraday control.",next:"Look for acceptance, rejection and retests around VWAP. Confirm the session reset and feed volume are appropriate for the market."},
 {term:"Bollinger Bands",meaning:"A moving average with volatility bands, commonly two standard deviations away.",why:"Band expansion signals rising volatility; contraction signals compression. Touching a band alone is not a reversal signal.",next:"Use trend and volatility regime. In a trend, price can ride a band; in a range, wait for rejection and confirmation."},
 {term:"RSI 14",meaning:"A momentum oscillator from 0 to 100 comparing recent average gains and losses.",why:"High/low readings describe momentum and possible stretched conditions, not automatic overbought/oversold reversals.",next:"Check divergence and structure. In strong trends RSI can stay elevated or depressed; avoid countertrend entries from RSI alone."},
 {term:"MACD / SIGNAL / HISTOGRAM",meaning:"The difference between fast and slow moving averages, its signal average, and the histogram showing their separation.",why:"Crosses and histogram changes describe momentum shifts, but lag and can reverse quickly in sideways markets.",next:"Confirm with price structure and volume. A crossover without a break/retest is not an entry instruction."},
 {term:"ADX",meaning:"Average Directional Index, a measure of trend strength rather than bullish or bearish direction.",why:"A rising/high ADX can indicate stronger directional movement; low ADX often accompanies weak or ranging conditions.",next:"Use DI/trend direction alongside ADX. Reduce breakout confidence in low-strength or transition regimes."},
 {term:"ATR",meaning:"Average True Range, a measure of recent volatility.",why:"It estimates typical movement size, not direction, and helps contextualise stop distance and position sizing.",next:"Use it to avoid stops inside normal noise and to scale risk. Recalculate when volatility changes."},
 {term:"VOLUME / RVOL",meaning:"Traded quantity and relative volume versus a recent baseline.",why:"Expansion can validate participation; low volume can weaken breakouts. Volume alone does not reveal buyer or seller intent.",next:"Seek volume expansion on a confirmed break and healthy retest. Check venue-specific volume units and avoid comparing unlike feeds."},
 {term:"ORDER BOOK WALL / OBI / IMBALANCE",meaning:"Displayed bid/ask depth and its relative size imbalance; walls are unusually large visible levels.",why:"Displayed liquidity can be cancelled, spoofed, replenished or consumed. A snapshot is not guaranteed executable depth.",next:"Check persistence across snapshots, spread and actual trades. Treat a single wall or imbalance as context, not a trade signal."},
 {term:"DELTA / CVD / FOOTPRINT",meaning:"Delta estimates aggressive buy minus sell volume; CVD accumulates delta; footprint groups traded volume by price.",why:"They help compare aggressive execution with price movement and can reveal absorption or divergence, subject to trade-side classification quality.",next:"Confirm the tape is fresh and venue-native. Look for sustained delta plus price acceptance; divergence is a warning to investigate, not an automatic reversal."},
 {term:"SPREAD / MICROPRICE",meaning:"Spread is the gap between best ask and bid. Microprice weights the mid using displayed top-of-book size.",why:"Wide spreads raise entry/exit costs; microprice can indicate short-term top-of-book pressure but is sensitive to cancellations.",next:"Do not enter when spread or depth fails the strategy's cost/liquidity gate. Recheck immediately before order submission."},
 {term:"FUNDING / OPEN INTEREST",meaning:"Futures funding is a periodic payment between long and short positions; open interest is outstanding contracts.",why:"Extreme funding can indicate crowded positioning; rising OI with price may indicate new participation but does not reveal direction by itself.",next:"Use as derivatives context alongside price and volume. Confirm contract type, timestamp and venue; missing values remain unavailable."},
 {term:"POC / VAH / VAL",meaning:"Volume Profile Point of Control is the price with the most volume in the profile; Value Area High/Low bound the modelled value area.",why:"They describe where the selected window traded most and its value area, not guaranteed support/resistance.",next:"Watch acceptance or rejection at value edges and POC. Check profile window and volume-distribution approximation."},
 {term:"SCORE / CONVICTION / BUY / SELL / HOLD",meaning:"ETI's rule-based signal summary and evidence score. HOLD/WAIT means no qualified direction under current gates.",why:"Scores are heuristic confluence/evidence measures, not probabilities of profit or guarantees.",next:"Read supporting and opposing evidence, regime, data freshness, expiry and validation blockers. Only a tradeable signal with an independent risk-approved plan may proceed."}
];
function renderChartInterpretation(){
 const host=$("tt-chart-readout"),next=$("tt-chart-next"),glossary=$("tt-chart-glossary");if(!host||!next||!glossary)return;
 const sig=S.signal,lf=S.liquidityFvg,rows=S.candles||[],last=rows.at(-1),now=Date.now();
 const add=(parent,title,detail)=>{const d=document.createElement("div");d.className="tt-inst-row";const a=document.createElement("span"),b=document.createElement("b");a.textContent=title;b.textContent=detail;d.append(a,b);parent.append(d);};
 host.replaceChildren();next.replaceChildren();glossary.replaceChildren();
 $("tt-chart-interpretation-status").textContent=rows.length?S.symbol+" · "+S.interval+" · "+rows.length+" candles":"Market data unavailable";
 if(!last){add(host,"Market read","No candle data. Do not trade until the selected venue feed is restored.");add(next,"Next action","Refresh market data; do not infer a direction from missing chart data.");}
 else{
  add(host,"Latest chart price",px(last.close)+" · "+S.venue.toUpperCase()+" "+S.market.toUpperCase());
  add(host,"Signal",sig?(sig.action||"WAIT")+" · "+(sig.classification||sig.conviction||"classification unavailable"):"Unavailable");
  add(host,"Signal gate",sig?(sig.tradeable?"Trade-plan gate passed; execution checks still required":sig.gatedAction||"Not tradeable / wait"):"No validated signal");
  add(host,"Market regime",sig&&sig.regime?(sig.regime.state||sig.regime.regime||"available"):"Unavailable");
  const expiry=sig&&sig.expiresAt?Date.parse(sig.expiresAt):NaN;
  if(Number.isFinite(expiry))add(host,"Signal validity",expiry>now?"Expires "+new Date(expiry).toLocaleTimeString():"Expired · refresh analysis");
  const d=lf&&lf.precision&&lf.precision.best;
  add(host,"Liquidity + FVG",lf?(lf.autopilotEligible?"Qualified "+lf.direction+" setup": "WAIT · "+((lf.eligibilityReasons||lf.blocks||[]).slice(0,2).join("; ")||"No qualified setup")):"Unavailable");
  if(d){add(host,"FVG entry reference",px(d.entry&&d.entry.price)+" · "+d.direction+" · "+(d.riskReward?fmt(d.riskReward,2)+"R":"R/R unavailable"));add(host,"FVG zone",px(d.zone&&d.zone.lower)+" – "+px(d.zone&&d.zone.upper));}
  const sw=lf&&lf.latestSweep;if(sw)add(host,"Latest sweep",String(sw.side||"liquidity").toUpperCase()+" · "+px(sw.level)+" · "+(sw.direction||"reaction pending"));
  const band=lf&&lf.manipulation&&lf.manipulation.estimatedReach;if(band)add(host,"Estimated sweep reach",px(band.low)+" – "+px(band.high)+" · scenario band only");
  const cur=(S.smc||[]).find(x=>x[0]===S.interval),a=cur&&cur[1],ev=a&&a.structure&&a.structure.events||[];
  if(a){add(host,"Structure",((a.structure&&a.structure.trend)||"unavailable")+" · "+((a.structure&&a.structure.stance)||"stance unavailable"));add(host,"Latest structure event",ev.length?(ev[ev.length-1].type||ev[ev.length-1].event||"event")+" · "+px(ev[ev.length-1].price||ev[ev.length-1].level):"No recent confirmed event");}
  if(S.orderFlow){add(host,"Order flow", "Delta "+fmt(S.orderFlow.delta,5)+" · "+fmt(S.orderFlow.deltaPct,2)+"% · "+(S.orderFlow.bookFresh?"fresh book":"book freshness unconfirmed"));add(host,"Spread / imbalance",fmt(S.orderFlow.spreadBps,2)+" bps · "+fmt(S.orderFlow.imbalance,3));}
  if(S.omni)add(host,"Independent cross-check",String(S.omni.decision||"unavailable")+" · "+(S.omni.tradeable?"trade plan valid":"not independently tradeable"));
  const omniDecision=String(S.omni&&S.omni.decision||"").toUpperCase(),signalSide=String(sig&&sig.action||"").toUpperCase();const omniConflict=!!omniDecision&&((signalSide==="BUY"&&["SELL","SHORT"].includes(omniDecision))||(signalSide==="SELL"&&["BUY","LONG"].includes(omniDecision)));if(omniConflict)add(host,"Engine disagreement","Omnisignal "+omniDecision+" conflicts with chart signal "+signalSide+" · stand aside");
  if(!sig||!sig.tradeable||!Number.isFinite(expiry)||expiry<=now||!["BUY","SELL"].includes(signalSide)||(lf&&!lf.autopilotEligible)||omniConflict){add(next,"Recommendation","WAIT / DO NOT ENTER. Signal is missing, blocked, expired, not a directional BUY/SELL, liquidity-FVG is unqualified, or an independent engine disagrees. Refresh and resolve the displayed blockers.");}
  else{add(next,"Recommendation","A qualified signal exists, not an unconditional instruction. Recheck the latest completed candle, venue data, spread, risk limits and execution preflight before considering entry.");}
  if(lf&&!lf.autopilotEligible)add(next,"Liquidity gate","Do not use the FVG as an entry while ETI reports it unqualified. Resolve: "+((lf.blocks||lf.eligibilityReasons||[]).slice(0,3).join("; ")||"insufficient confluence"));
  if(sw)add(next,"After a sweep","Wait for reclaim/acceptance, directional displacement and BOS/CHoCH, then a retest. If price accepts beyond the swept level, do not assume reversal.");
  add(next,"Order annotation","ORDER is only a chart reference unless ETI can match it to a live exchange order ID and status. Verify in authenticated order history before managing a supposed position.");
  add(next,"Risk / exit","Use the planned structural stop; never widen it. Take profit only at planned targets and reassess if opposing structure, stale data or expiry invalidates the thesis.");
 }
 CHART_GLOSSARY.forEach(g=>{const d=document.createElement("details"),s=document.createElement("summary"),body=document.createElement("div");d.className="tt-chart-term";s.textContent=g.term;body.className="tt-chart-term-body";body.textContent="Meaning: "+g.meaning+" Why it matters: "+g.why+" What to do: "+g.next;d.append(s,body);glossary.append(d);});
}
function renderLiquidityFvg(){
 const d=S.liquidityFvg;if(!d){$("tt-lf-status").textContent="Unavailable · fail closed";["tt-lf-action","tt-lf-score","tt-lf-risk","tt-lf-side","tt-lf-level","tt-lf-band","tt-lf-entry","tt-lf-rr"].forEach(id=>$(id).textContent="—");$("tt-lf-pools").replaceChildren();$("tt-lf-evidence").textContent="No current combined analysis. No setup is authorized.";renderChartInterpretation();return;}
 $("tt-lf-status").textContent="Updated "+new Date().toLocaleTimeString()+" · "+S.interval;
 $("tt-lf-action").textContent=d.autopilotEligible?d.direction:"WAIT";$("tt-lf-action").style.color=d.direction==="BUY"?"#63e6bd":d.direction==="SELL"?"#ff91a0":"#f2c879";
 $("tt-lf-score").textContent=String(d.score)+"/100";$("tt-lf-risk").textContent=(d.manipulation&&d.manipulation.level||"unknown").toUpperCase()+" · "+fmt(d.manipulation&&d.manipulation.score||0,0);
 $("tt-lf-side").textContent=String(d.manipulation&&d.manipulation.likelySide||"none").replace(/_/g," ").toUpperCase();
 $("tt-lf-level").textContent=d.manipulation&&d.manipulation.likelySweepPrice?px(d.manipulation.likelySweepPrice):"—";
 const band=d.manipulation&&d.manipulation.estimatedReach;$("tt-lf-band").textContent=band?px(band.low)+" – "+px(band.high):"—";
 const z=d.precision&&d.precision.best;$("tt-lf-entry").textContent=z?px(z.entry.price):"—";$("tt-lf-rr").textContent=z&&z.riskReward?fmt(z.riskReward,2)+"R":"—";
 $("tt-lf-evidence").textContent=[...(d.manipulation&&d.manipulation.evidence||[]),...(d.eligibilityReasons||[]),...(d.blocks||[])].slice(0,6).join(" · ")||"No qualified setup.";
 const pools=(d.pools||[]).slice(0,8);$("tt-lf-pools").replaceChildren(...pools.map(p=>{const e=document.createElement("div");e.className="tt-liq-pool";const a=document.createElement("span"),b=document.createElement("b");a.textContent=(p.side==="buy_side"?"BUY-SIDE":"SELL-SIDE")+" · "+p.touches+" tests · "+p.distanceAtr+" ATR";b.textContent=px(p.price);e.append(a,b);return e;}));renderChartInterpretation();
}
async function loadLiquidityFvg(){
 if(!S.candles.length)return;const key=[S.venue,S.market,S.category,S.symbol,S.interval,S.candles.at(-1).time].join("|");if(S.lfKey===key&&Date.now()-(S.lfAt||0)<30000)return;S.lfKey=key;
 try{const rows=S.candles.map(x=>[x.time*1000,x.open,x.high,x.low,x.close,x.volume]);const r=await fetch("/api/analysis/liquidity-fvg?symbol="+encodeURIComponent(S.symbol)+"&timeframe="+encodeURIComponent(S.interval)+"&assetClass=crypto",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({candles:{[S.interval]:rows}}),cache:"no-store"});const d=await r.json();if(!r.ok)throw new Error(d.detail||d.error||"HTTP "+r.status);if([S.venue,S.market,S.category,S.symbol,S.interval,S.candles.at(-1).time].join("|")!==key)return;S.liquidityFvg=d;S.lfAt=Date.now();renderLiquidityFvg();render();}catch(e){S.liquidityFvg=null;S.lfAt=Date.now();$("tt-lf-status").textContent="Analysis unavailable · "+(e.message||"data error");renderLiquidityFvg();}
}
function renderSignal(sig){S.signal=sig;renderChartInterpretation();capturePricePrecision([sig.entry,sig.stopLoss].concat((sig.targets||[]).map(x=>x.price)));const action=sig.action||"WAIT";$("tt-signal-action").textContent=action;$("tt-signal-action").style.color=action==="BUY"?"#63e6bd":action==="SELL"?"#ff91a0":"#f2c879";$("tt-signal-score").textContent=sig.score==null?"—":String(sig.score);$("tt-signal-conviction").textContent=sig.conviction||"—";$("tt-signal-regime").textContent=sig.regime&&sig.regime.state||"—";$("tt-signal-gate").textContent=sig.tradeable?"TRADEABLE":sig.gatedAction||"WAIT";$("tt-signal-entry").textContent=px(sig.entry);$("tt-signal-stop").textContent=px(sig.stopLoss);$("tt-signal-tp1").textContent=px(sig.targets&&sig.targets[0]&&sig.targets[0].price);$("tt-signal-tp2").textContent=px(sig.targets&&sig.targets[1]&&sig.targets[1].price);$("tt-signal-note").textContent=(sig.evidence||[]).slice(0,3).join(" · ")||"No explanatory evidence was returned.";render();if(sig.chart){const times=sig.chart.times||[];const series=(key)=>times.map((t,i)=>({time:Math.floor(t/1000),value:sig.chart[key]&&sig.chart[key][i]})).filter(x=>Number.isFinite(x.value));if(S.ema20&&series("ema20").length)S.ema20.setData(series("ema20"));if(S.ema50&&series("ema50").length)S.ema50.setData(series("ema50"));}}
async function loadSignal(candles){try{const r=await fetch("/api/signals",{method:"POST",headers:{"content-type":"application/json","accept":"application/json"},body:JSON.stringify({symbol:S.symbol,interval:S.interval,window:300,provider:S.venue,market:S.market,category:S.category,candles:candles})});const sig=await r.json();if(!r.ok)throw new Error(sig.detail||sig.error||"ETIAlgo signal unavailable");renderSignal(sig);}catch(e){S.signal=null;$("tt-signal-action").textContent="UNAVAILABLE";$("tt-signal-score").textContent="—";$("tt-signal-conviction").textContent="—";$("tt-signal-regime").textContent="—";$("tt-signal-gate").textContent="NO DATA";$("tt-signal-note").textContent="ETIAlgo could not analyse "+S.venue+" candles: "+e.message;}}

