function rowHtml(label,value,detail){return '<div class="tt-inst-row"><span>'+label+'</span><b>'+value+(detail?' · '+detail:'')+'</b></div>';}
function calcProfile(rows,bins=32){if(rows.length<20)return null;const lo=Math.min(...rows.map(x=>x.low)),hi=Math.max(...rows.map(x=>x.high));if(!(hi>lo))return null;const step=(hi-lo)/bins,vol=Array(bins).fill(0);rows.forEach(c=>{const a=Math.max(0,Math.min(bins-1,Math.floor((c.low-lo)/step))),b=Math.max(0,Math.min(bins-1,Math.floor((c.high-lo)/step)));for(let i=a;i<=b;i++)vol[i]+=c.volume/(b-a+1);});const total=vol.reduce((a,b)=>a+b,0),poc=vol.indexOf(Math.max(...vol));let l=poc,r=poc,acc=vol[poc];while(acc<total*.7&&(l>0||r<bins-1)){if(l>0&&(r===bins-1||vol[l-1]>=vol[r+1]))acc+=vol[--l];else if(r<bins-1)acc+=vol[++r];else break;}return {lo,hi,step,vol,poc,l,r,total};}
function renderProfile(){const p=calcProfile(S.candles);if(!p){$("tt-profile").textContent="At least 20 candles are required.";return;}const vah=p.lo+(p.r+1)*p.step,val=p.lo+p.l*p.step,poc=p.lo+(p.poc+.5)*p.step; $("tt-vp-poc").textContent=px(poc);$("tt-vp-value").textContent=px(vah)+" / "+px(val);const last=S.candles.at(-1).close;$("tt-vp-location").textContent=(last>vah?"Price above value":last<val?"Price below value":"Price inside value")+" · "+fmt(p.total,2)+" volume units";const max=Math.max(...p.vol);$("tt-profile").replaceChildren(...p.vol.map((v,i)=>{const d=document.createElement("div");d.className="tt-profile-row"+(i===p.poc?" poc":"");const a=document.createElement("span");a.textContent=px(p.lo+(i+.5)*p.step);const bar=document.createElement("div");bar.className="tt-profile-bar";const fill=document.createElement("i");fill.style.width=(max?v/max*100:0)+"%";bar.append(fill);const n=document.createElement("span");n.textContent=fmt(v,1);d.append(a,bar,n);return d;}).reverse());}
async function loadAdvancedProfile(){
 if(!S.candles.length)return;const key=[S.venue,S.market,S.category,S.symbol,S.candles.at(-1).time].join("|");const status=$("tt-vp-status");if(status)status.textContent="Calculating trade-level volume profile…";
 try{
  const trades=(S.trades||[]).map(t=>{const maker=t.isBuyerMaker!==undefined?t.isBuyerMaker:t.m;const side=maker===true||maker==="true"?"sell":maker===false||maker==="false"?"buy":String(t.side||"").toLowerCase();if(side!=="buy"&&side!=="sell")return null;return{time:Number(t.time??t.timestamp),price:Number(t.price??t.p),qty:Number(t.qty??t.q??t.size),isBuyerMaker:side==="sell"};}).filter(t=>t&&Number.isFinite(t.time)&&t.time>0&&Number.isFinite(t.price)&&t.price>0&&Number.isFinite(t.qty)&&t.qty>0);
  const candles=S.candles.map(x=>[x.time*1000,x.open,x.high,x.low,x.close,x.volume]);
  const qs=new URLSearchParams({symbol:S.symbol,venue:S.venue,market:S.market});
  const response=await fetch("/api/analysis/volume-profile?"+qs,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trades:trades.length?trades:undefined,candles,provider:S.venue}),cache:"no-store"});
  const data=await response.json();if(!response.ok)throw new Error(data.detail||data.error||"HTTP "+response.status);
  if([S.venue,S.market,S.category,S.symbol,S.candles.at(-1).time].join("|")!==key)return;
  const profile=(data.profiles||[])[0];if(!profile||profile.status!=="ok")throw new Error("No valid profile returned");
  $("tt-vp-poc").textContent=px(profile.poc);$("tt-vp-value").textContent=px(profile.vah)+" / "+px(profile.val);
  $("tt-vp-location").textContent=String(profile.location||"").replace(/_/g," ")+" · "+profile.sourceCoverage.method+" · "+(profile.freshness.stale?"trade feed stale":"live trade feed");
  const nodes=profile.bins||[],max=Math.max(1,...nodes.map(x=>x.volume));$("tt-profile").replaceChildren(...nodes.map((x,i)=>{const d=document.createElement("div");d.className="tt-profile-row"+(i===profile.pocIndex?" poc":"");const a=document.createElement("span");a.textContent=px(x.price);const bar=document.createElement("div");bar.className="tt-profile-bar";const fill=document.createElement("i");fill.style.width=(x.volume/max*100)+"%";bar.append(fill);const n=document.createElement("span");n.textContent=fmt(x.volume,3);d.append(a,bar,n);return d;}).reverse());
  if(status)status.textContent=profile.sourceCoverage.exchangeTradeCount+" exchange prints · "+profile.sourceCoverage.method+" · "+new Date(data.generatedAt).toLocaleTimeString();
 }catch(e){if(status)status.textContent="Advanced profile unavailable · "+(e.message||"feed error")+" · candle estimate retained";}
}
function renderFlow(){const rows=S.trades||[];let buy=0,sell=0;rows.forEach(t=>{const q=Number(t.qty||t.q||t.size||0),maker=t.isBuyerMaker!==undefined?t.isBuyerMaker:t.m;if(maker===true||maker==="true")sell+=q;else if(maker===false||maker==="false")buy+=q;});const total=buy+sell,delta=buy-sell;$("tt-flow").innerHTML=rowHtml("Sample buy volume",fmt(buy,5))+rowHtml("Sample sell volume",fmt(sell,5))+rowHtml("Rolling trade delta",fmt(delta,5),total?fmt(delta/total*100,1)+"%":"—");}
function renderOrderFlow(depth,trades){const tape=trades||[],book=depth||null;let buy=0,sell=0,buyNotional=0,sellNotional=0; tape.forEach(t=>{const q=Number(t.qty??t.q??t.size??0),p=Number(t.price??t.p??0),maker=t.isBuyerMaker!==undefined?t.isBuyerMaker:t.m;if(!(q>0&&p>0))return;if(maker===true||maker==="true"){sell+=q;sellNotional+=q*p;}else if(maker===false||maker==="false"){buy+=q;buyNotional+=q*p;}});const total=buy+sell,delta=buy-sell,deltaPct=total?delta/total*100:null;let spread=null,spreadBps=null,imbalance=null,micro=null,bidQty=0,askQty=0,bidNotional=0,askNotional=0,bidWall=null,askWall=null,bookAge=null;if(book&&Array.isArray(book.bids)&&Array.isArray(book.asks)&&book.bids.length&&book.asks.length){const bids=book.bids.slice().sort((a,b)=>Number(b[0])-Number(a[0])),asks=book.asks.slice().sort((a,b)=>Number(a[0])-Number(b[0])),bb=Number(bids[0][0]),ba=Number(asks[0][0]),mid=(bb+ba)/2;spread=ba-bb;spreadBps=mid>0?spread/mid*10000:null;bids.slice(0,10).forEach(x=>{const q=Number(x[1]),p=Number(x[0]);bidQty+=q;bidNotional+=q*p;if(!bidWall||q>bidWall.qty)bidWall={price:p,qty:q};});asks.slice(0,10).forEach(x=>{const q=Number(x[1]),p=Number(x[0]);askQty+=q;askNotional+=q*p;if(!askWall||q>askWall.qty)askWall={price:p,qty:q};});const sum=bidQty+askQty;imbalance=sum?(bidQty-askQty)/sum:null;micro=sum?(ba*bidQty+bb*askQty)/sum:null;bookAge=book.timestamp?Math.max(0,Date.now()-book.timestamp):0;}const fresh=bookAge===null||bookAge<=180000;const set=(id,v,cls)=>{const n=$(id);n.textContent=v;n.className=cls||"";};set("tt-of-buy",total?fmt(buy,6):"—","tt-flow-positive");set("tt-of-sell",total?fmt(sell,6):"—","tt-flow-negative");set("tt-of-delta",total?fmt(delta,6):"—",delta>0?"tt-flow-positive":delta<0?"tt-flow-negative":"");set("tt-of-delta-pct",deltaPct===null?"—":fmt(deltaPct,2)+"%",delta>0?"tt-flow-positive":delta<0?"tt-flow-negative":"");set("tt-of-imbalance",imbalance===null||!fresh?"—":fmt(imbalance*100,2)+"%",imbalance>0?"tt-flow-positive":imbalance<0?"tt-flow-negative":"");set("tt-of-spread",spreadBps===null||!fresh?"—":fmt(spreadBps,2)+" bps");set("tt-of-microprice",micro===null||!fresh?"—":px(micro));set("tt-of-depth",book&&fresh?bidQty.toFixed(4)+" / "+askQty.toFixed(4):"Unavailable");const statusText=(total? tape.length+" public prints · sample delta "+(delta>0?"buy-led":delta<0?"sell-led":"balanced") :"Trade tape unavailable")+(book?(fresh?" · book age "+Math.round(bookAge/1000)+"s":" · stale book snapshot") :" · depth unavailable");$("tt-flow-status").textContent=statusText;const details=[];if(book&&fresh){details.push("Top-10 depth imbalance "+(imbalance===null?"unavailable":fmt(imbalance*100,2)+"%")+" (bid "+fmt(bidQty,5)+" vs ask "+fmt(askQty,5)+")");if(bidWall)details.push("Largest bid level "+px(bidWall.price)+" · "+fmt(bidWall.qty,5));if(askWall)details.push("Largest ask level "+px(askWall.price)+" · "+fmt(askWall.qty,5));if(spreadBps!==null)details.push("Quoted spread "+fmt(spreadBps,2)+" bps");}if(total)details.push("Aggressor delta "+fmt(delta,6)+" base units / "+fmt(deltaPct,2)+"% across "+tape.length+" prints");$("tt-of-detail").textContent=details.join(" · ")||"Order-flow inputs unavailable; no synthetic values are generated.";S.orderFlow={buy,sell,delta,deltaPct,imbalance,spreadBps,micro,bookFresh:fresh,tradeCount:tape.length,depthLevels:book?Math.min(book.bids.length,10)+"/"+Math.min(book.asks.length,10):"unavailable"};renderChartInterpretation();}
async function loadOmniSignal(){const key=S.venue+"|"+S.market+"|"+S.category+"|"+S.symbol;if(S.omniKey===key&&Date.now()-S.omniAt<60000)return;S.omniKey=key;S.omniAt=Date.now();const out=$("tt-omni-result");out.textContent="ETIAlgo is analysing the selected venue with its existing independent validation and risk gates…";try{const p=new URLSearchParams({symbol:S.symbol,strategy:"intraday",engines:"swift,gainz",venue:S.venue,provider:S.venue,market:S.market,category:S.category});const r=await fetch("/api/omnisignal?"+p,{cache:"no-store"});const response=await r.json();if(!r.ok)throw new Error(response.message||response.error||"Omnisignal unavailable");S.omni=response;renderChartInterpretation();const v=response.validation||{},liq=response.liquidity||{};out.textContent="ETIAlgo "+response.decision+" · confidence "+(response.confidence??"—")+" · validation "+(v.classification||"not returned")+" · liquidity "+(liq.available?"spread "+fmt(liq.spreadBps,2)+" bps":"unavailable")+" · "+(response.tradeable?"trade plan valid":"not tradeable / analysis only")+". "+(response.reasons||[]).slice(0,3).join(" · ")+". submitsOrder="+response.submitsOrder+"; liveExecutionAllowed="+response.liveExecutionAllowed+".";}catch(e){S.omni=null;S.omniAt=0;out.textContent="ETIAlgo advanced cross-check unavailable: "+e.message+". The existing ETIAlgo signal and all execution safeguards remain unchanged.";}}

function renderDeepOrderFlow(data){
 const foot=$("tt-footprint"),cvd=$("tt-deep-cvd"),hist=$("tt-liquidity-persistence"),note=$("tt-liquidity-note"),statusEl=$("tt-flow-status");
 if(!data){foot.textContent="No validated footprint data.";cvd.textContent="CVD unavailable.";hist.textContent="No historical depth samples.";note.textContent="A valid exchange trade tape and order book are required.";return;}
 const rows=(data.footprint||[]).slice().sort((a,b)=>b.totalVolume-a.totalVolume).slice(0,16);
 const header='<div class="tt-footprint-row tt-footprint-head"><span>PRICE</span><span>BUY</span><span>SELL</span><span>DELTA</span><span>BIAS</span></div>';
 foot.innerHTML=header+rows.map(x=>'<div class="tt-footprint-row"><span>'+px(x.price)+'</span><span class="tt-flow-positive">'+fmt(x.buyVolume,5)+'</span><span class="tt-flow-negative">'+fmt(x.sellVolume,5)+'</span><span class="'+(x.delta>0?'tt-flow-positive':x.delta<0?'tt-flow-negative':'')+'">'+fmt(x.delta,5)+'</span><span>'+String(x.imbalance||"balanced").toUpperCase()+'</span></div>').join("")||"No price buckets in this sample.";
 const t=data.tape||{},last=(t.cvd||[]).slice(-1)[0];
 cvd.innerHTML='<div class="tt-inst-row"><span>Sample cumulative delta</span><b class="'+(Number(t.cumulativeDelta)>0?'tt-flow-positive':Number(t.cumulativeDelta)<0?'tt-flow-negative':'')+'">'+fmt(t.cumulativeDelta,6)+'</b></div><div class="tt-inst-row"><span>Sample delta</span><b>'+fmt(t.delta,6)+' ('+fmt(t.deltaPct,2)+'%)</b></div><div class="tt-inst-row"><span>Price change</span><b>'+fmt(t.priceChangePct,4)+'%</b></div><div class="tt-inst-row"><span>Last CVD observation</span><b>'+(last?fmt(last.value,6):"—")+'</b></div>';
 const p=data.liquidityHistory||{},levels=[...(p.persistentLevels&&p.persistentLevels.bids||[]).map(x=>({...x,side:"BID"})),...(p.persistentLevels&&p.persistentLevels.asks||[]).map(x=>({...x,side:"ASK"}))].sort((a,b)=>b.persistencePct*b.averageQty-a.persistencePct*a.averageQty).slice(0,12);
 hist.innerHTML=levels.map(x=>'<div class="tt-persistence-row"><span>'+x.side+' · '+px(x.price)+'</span><b>'+fmt(x.persistencePct,1)+'% · '+fmt(x.averageQty,5)+'</b></div>').join("")||"No persistent levels identified yet.";
 note.textContent=(p.note||"Depth history unavailable.")+" Samples: "+(p.sampleCount||0)+".";
 if(statusEl&&p.status==="recorded")statusEl.textContent+=" · history samples "+(p.sampleCount||0);
}
async function loadDeepOrderFlow(){
 const key=[S.venue,S.market,S.category,S.symbol,S.interval].join("|");
 const raw=(S.trades||[]).slice(0,500).map(t=>({time:Number(t.time??t.T??t.timestamp),price:Number(t.price??t.p),qty:Number(t.qty??t.q??t.size),isBuyerMaker:typeof t.isBuyerMaker==="boolean"?t.isBuyerMaker:Boolean(t.m)}));
 const book=S.depth&&Array.isArray(S.depth.bids)&&Array.isArray(S.depth.asks)?{bids:S.depth.bids,asks:S.depth.asks}:null;
 if(!raw.length||!book||!book.bids.length||!book.asks.length){renderDeepOrderFlow(null);return;}
 const candles=(S.candles||[]).slice(-60).map(x=>[Number(x.time)*1000,Number(x.open),Number(x.high),Number(x.low),Number(x.close),Number(x.volume)]);
 try{
  const response=await fetch("/api/analysis/orderflow",{method:"POST",headers:{"content-type":"application/json"},cache:"no-store",body:JSON.stringify({symbol:S.symbol,venue:S.venue,market:S.market,category:S.category,provider:S.venue,trades:raw,depth:book,candles})});
  const data=await response.json();
  if(!response.ok)throw new Error(data.detail||data.error||"Order-flow analysis failed ("+response.status+")");
  if(key!==[S.venue,S.market,S.category,S.symbol,S.interval].join("|"))return;
  S.orderFlow=data;renderDeepOrderFlow(data);
 }catch(e){if(key===[S.venue,S.market,S.category,S.symbol,S.interval].join("|")){$("tt-flow-status").textContent="Advanced footprint unavailable";$("tt-footprint").textContent=e.message||"Order-flow analysis unavailable";$("tt-deep-cvd").textContent="CVD unavailable.";}}
}
