function renderInstitutional(){const items=S.smc||[];const current=items.find(x=>x[0]===S.interval)||items[Math.min(2,items.length-1)]||items[0];if(current){const a=current[1];$("tt-smc-trend").textContent=a.structure&&a.structure.trend||a.status||"—";$("tt-smc-stance").textContent=a.structure&&a.structure.stance||a.reason||"—";$("tt-smc-event").textContent=(a.structure&&a.structure.events||[]).slice(-1).map(x=>x.type||x.event||"Structure event").join(", ")||"No recent break";$("tt-smc-data").textContent=(a.dataQuality&&a.dataQuality.candles||a.candles||0)+" closed candles · "+(a.dataQuality&&a.dataQuality.provider||"exchange feed");}
$("tt-mtf").replaceChildren(...items.map(([tf,a])=>{const d=document.createElement("div");d.className="tt-inst-row";const l=document.createElement("span");l.textContent=tf;const b=document.createElement("b");b.textContent=(a.structure&&a.structure.trend||a.status||"unknown")+" / "+(a.structure&&a.structure.stance||"neutral");d.append(l,b);return d;}));
const obs=current&&current[1].orderBlocks||[],pools=current&&current[1].liquidityPools||[],sweeps=current&&current[1].liquiditySweeps||[],events=current&&current[1].structure&&current[1].structure.events||[];const obRows=obs.slice(-8).map(o=>rowHtml(o.kind.toUpperCase()+" OB",px(o.low)+" – "+px(o.high),o.invalidated?"invalidated":o.mitigated?"mitigated":o.hasFVG?"FVG confluence":"unmitigated"));pools.slice(-6).forEach(p=>obRows.push(rowHtml(p.side.replace("_"," ").toUpperCase(),px(p.price),p.touches+" touches")));$("tt-ob").innerHTML=obRows.join("")||"No confirmed order blocks or equal-level pools.";const ev=sweeps.slice(-5).map(x=>rowHtml(x.side.replace("_"," ").toUpperCase()+" sweep",px(x.level),x.reclaimed?"reclaimed":"not reclaimed")).concat(events.slice(-5).map(x=>rowHtml(x.type||"Structure",x.direction||x.level||"—",x.time?new Date(x.time).toLocaleString():"confirmed")));$("tt-events").innerHTML=ev.join("")||"No recent confirmed events.";
if(S.candle){S.institutionalLines.forEach(x=>{try{S.candle.removePriceLine(x)}catch(e){}});S.institutionalLines=[];}if(current&&S.candle){const levels=[...obs.filter(x=>!x.invalidated).slice(-6).flatMap(x=>[{price:x.high,color:x.kind==="bullish"?"#25d5a0":"#f36a80",title:x.kind.toUpperCase()+" OB high"},{price:x.low,color:x.kind==="bullish"?"#25d5a0":"#f36a80",title:x.kind.toUpperCase()+" OB low"}]),...pools.slice(-5).map(x=>({price:x.price,color:"#d5a8ff",title:x.side.replace("_"," ")+" liquidity"}))];levels.forEach(x=>{if(Number.isFinite(x.price)&&x.price>0)S.institutionalLines.push(S.candle.createPriceLine({price:x.price,color:x.color,lineWidth:1,lineStyle:2,axisLabelVisible:true,title:x.title}));});}}
